CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_sanction]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_sanction]
	(
		[apuk_appealdate],
		[apuk_appealed],
		[apuk_appealoutcome],
		[apuk_appealstatus],
		[apuk_appealtribunalid],
		[apuk_appealtribunalid_entitytype],
		[apuk_appealtribunalidname],
		[apuk_chargeid],
		[apuk_chargeid_entitytype],
		[apuk_chargeidname],
		[apuk_fineamount],
		[apuk_fineamount_base],
		[apuk_fineincluded],
		[apuk_finelevel],
		[apuk_name],
		[apuk_rehearingrequired],
		[apuk_sanctiondetails],
		[apuk_sanctionid],
		[apuk_sanctionidnumber],
		[apuk_sanctiontype],
		[apuk_tribunalid],
		[apuk_tribunalid_entitytype],
		[apuk_tribunalidname],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[exchangerate],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[transactioncurrencyidname],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_appealdate],
		stg.[apuk_appealed],
		stg.[apuk_appealoutcome],
		stg.[apuk_appealstatus],
		stg.[apuk_appealtribunalid],
		stg.[apuk_appealtribunalid_entitytype],
		stg.[apuk_appealtribunalidname],
		stg.[apuk_chargeid],
		stg.[apuk_chargeid_entitytype],
		stg.[apuk_chargeidname],
		stg.[apuk_fineamount],
		stg.[apuk_fineamount_base],
		stg.[apuk_fineincluded],
		stg.[apuk_finelevel],
		stg.[apuk_name],
		stg.[apuk_rehearingrequired],
		stg.[apuk_sanctiondetails],
		stg.[apuk_sanctionid],
		stg.[apuk_sanctionidnumber],
		stg.[apuk_sanctiontype],
		stg.[apuk_tribunalid],
		stg.[apuk_tribunalid_entitytype],
		stg.[apuk_tribunalidname],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[exchangerate],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[transactioncurrencyidname],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_sanction] stg
		LEFT JOIN [synapse_ce].[apuk_sanction] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
